insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-data-is-the-world', 'world-ai-data-is-the-world', 'data-is-the-world', '5A - Data Is the World', 'A records-recovery sweep of Cipher Labs'' decommissioned storage turns up fragments that might be part of Echo''s original training data -- and every practical skill needed to find out whether they can actually be trusted.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-data-is-the-world-1', 'campaign-ai-data-is-the-world', 'the-recovered-fragments', 'The Recovered Fragments', 'Where the fragments came from, what they are made of, and the first three things that can quietly go wrong with any dataset.', 1),
  ('operation-ai-data-is-the-world-2', 'campaign-ai-data-is-the-world', 'making-it-usable', 'Making It Usable', 'Turning raw, damaged fragments into something a model -- or an investigation -- can actually use, and the audit that decides whether it worked.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-data-is-the-world-01', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-1', 'data-collection', 'Data Collection', 'A records-recovery sweep of Cipher Labs'' decommissioned storage turns up fragments that might be part of Echo''s original training data -- and the first rule of any data source is knowing where it actually came from.', 'beginner', ARRAY['maya','arjun'], null, null, '{"type":"simulation","simulationId":"data-collection-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 1),
  ('mission-ai-data-is-the-world-02', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-1', 'data-types', 'Data Types', 'Before any analysis can begin, every column in the recovered fragments needs to be sorted by what kind of data it actually is.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"data-types-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 2),
  ('mission-ai-data-is-the-world-03', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-1', 'missing-values', 'Missing Values', 'Not all missing data announces itself as a blank cell -- some of it hides in plain sight, dressed up as a normal-looking number.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"missing-values-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 3),
  ('mission-ai-data-is-the-world-04', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-1', 'duplicates', 'Duplicates', 'Recovered storage has a habit of handing back the same record twice. Finding the copies matters as much as finding the gaps.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"duplicates-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 4),
  ('mission-ai-data-is-the-world-05', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-1', 'outliers', 'Outliers', 'An extreme value could be a corrupted byte or the most important row in the dataset. Telling the difference is the whole job.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"outliers-sim"}'::jsonb, '{"xp":130,"credits":30}'::jsonb, false, 5),
  ('mission-ai-data-is-the-world-06', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-1', 'categorical-data', 'Categorical Data', 'Category labels are not numbers, and treating them like numbers -- or like each other -- breaks quietly downstream.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"categorical-data-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 6),
  ('mission-ai-data-is-the-world-07', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-2', 'encoding', 'Encoding', 'Turning category labels into numbers a model can use, without accidentally inventing an order that was never there.', 'beginner', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-data-is-the-world-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"encoding-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 7),
  ('mission-ai-data-is-the-world-08', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-2', 'scaling', 'Scaling', 'Left alone, a column measured in the thousands can drown out one measured in single digits -- not because it matters more, only because of its units.', 'beginner', ARRAY['arjun','byte'], '{"requiredMissionIds":["mission-ai-data-is-the-world-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"scaling-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 8),
  ('mission-ai-data-is-the-world-09', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-2', 'normalization', 'Normalization', 'Min-max normalization squeezes a column into a fixed range, using nothing but its own minimum and maximum -- and inherits every weakness that comes with that.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"normalization-sim"}'::jsonb, '{"xp":150,"credits":35}'::jsonb, false, 9),
  ('mission-ai-data-is-the-world-10', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-2', 'standardization', 'Standardization', 'Standardization recenters a column around its own mean and spread, trading a fixed range for a shape most statistical methods already assume.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"standardization-sim"}'::jsonb, '{"xp":160,"credits":35}'::jsonb, false, 10),
  ('mission-ai-data-is-the-world-11', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-2', 'data-quality', 'Data Quality', 'Missing values, duplicates, outliers, encoding, scaling -- all of it feeds one bigger question: is this data actually good enough to trust a conclusion built on it?', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"data-quality-sim"}'::jsonb, '{"xp":160,"credits":35}'::jsonb, false, 11),
  ('mission-ai-data-is-the-world-12', 'world-ai-data-is-the-world', 'campaign-ai-data-is-the-world', 'operation-ai-data-is-the-world-2', 'garbage-in', 'Garbage In', 'The recovered fragments, finally under real audit -- missing values, duplicates, corrupted values, and a verdict Cipher Division has to be honest enough to actually accept.', 'boss', ARRAY['maya','arjun'], '{"requiredMissionIds":["mission-ai-data-is-the-world-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"garbage-in-boss-sim"}'::jsonb, '{"xp":520,"credits":110,"badgeIds":["garbage-in"],"skillXp":{"data_engineering_ml":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-data-is-the-world-01', 1, 'arjun', 'Records-recovery finished its sweep of Cipher Labs'' decommissioned storage overnight. Every drive that survived the original wipe got pulled and imaged.'),
  ('mission-ai-data-is-the-world-01', 2, 'arjun', 'And there is something in it. Fragments -- not all of it, not even most of it -- but fragments that look like they could be part of Echo''s original training data.'),
  ('mission-ai-data-is-the-world-01', 3, 'maya', 'That is the biggest lead this investigation has had since Echo woke up. It is also exactly the moment people get sloppy, because they want it to be real.'),
  ('mission-ai-data-is-the-world-01', 4, 'arjun', 'I want it to be real too. That is not the same as trusting it yet. Before either of us gets ahead of this, we treat it like any other data source: figure out where it came from, how it was collected, and whether that history holds up.'),
  ('mission-ai-data-is-the-world-01', 5, 'maya', 'Agreed. Nothing about the fragments gets used to draw conclusions about Echo until we know how they were collected and what condition they are actually in.'),
  ('mission-ai-data-is-the-world-01', 6, 'arjun', 'Then let us start where every data problem actually starts -- not with the numbers, with the collection. Where data comes from decides what it can and cannot tell us, before we ever open a single row.'),

  ('mission-ai-data-is-the-world-02', 1, 'arjun', 'First pass on any dataset, before anything else: what type is each column actually? Numbers behave differently from categories, and categories behave differently from free text.'),
  ('mission-ai-data-is-the-world-02', 2, 'arjun', 'Get the type wrong and everything downstream breaks quietly -- average a column that is actually a category code and the result is a number that means nothing.'),
  ('mission-ai-data-is-the-world-02', 3, 'arjun', 'The recovered fragments are a mix: numeric fields, category-like codes, and a few columns that look like raw operator notes. Sort them first, before touching anything else.'),

  ('mission-ai-data-is-the-world-03', 1, 'arjun', 'Missing values are not always blank. Sometimes it is an empty cell. Sometimes somebody encoded "missing" as -999, or "N/A", or just left last year''s default sitting in the field.'),
  ('mission-ai-data-is-the-world-03', 2, 'arjun', 'In the recovered fragments, some of the damage is obvious -- empty cells. Some of it is not obvious at all, which is worse, because it looks like real data until you check.'),

  ('mission-ai-data-is-the-world-04', 1, 'arjun', 'Duplicates matter because they quietly change the weight of whatever they repeat. Ten copies of one row get treated as ten separate pieces of evidence, when they are really just one.'),
  ('mission-ai-data-is-the-world-04', 2, 'arjun', 'Recovered storage fragments are especially prone to this -- overlapping blocks from the imaging process can hand you the same record twice, sometimes with tiny formatting differences.'),

  ('mission-ai-data-is-the-world-05', 1, 'arjun', 'An outlier is a value far outside the range the rest of the column occupies. That alone does not tell you whether it is an error or the single most interesting row in the dataset.'),
  ('mission-ai-data-is-the-world-05', 2, 'arjun', 'Damaged, recovered storage produces plenty of fake outliers -- a corrupted byte can turn a normal number into something physically impossible. Real outliers exist too, and deleting those blindly throws away real signal.'),

  ('mission-ai-data-is-the-world-06', 1, 'arjun', 'Categorical data is any column whose values are labels drawn from a limited set, rather than numbers you can do arithmetic on. Region codes, status flags, priority levels -- all categorical.'),
  ('mission-ai-data-is-the-world-06', 2, 'arjun', 'Not all categories are equal, though. Some have a real order -- low, medium, high. Some do not -- there is no meaningful order between north and south. That difference decides how you are allowed to treat them next.'),

  ('mission-ai-data-is-the-world-07', 1, 'arjun', 'Encoding is how categorical labels become numbers a model can actually use. Two techniques cover most cases: one-hot encoding and ordinal, or label, encoding.'),
  ('mission-ai-data-is-the-world-07', 2, 'arjun', 'One-hot makes a separate zero-or-one column for each category -- safe for nominal data, because it never invents an order that is not there. Ordinal encoding maps categories to ranked numbers, which only makes sense when a real order exists.'),
  ('mission-ai-data-is-the-world-07', 3, 'byte', 'Get it backwards and you manufacture a lie. Label-encode north, south, east, west as 0, 1, 2, 3, and a model may read that as "west is three times north." There is no such relationship. It never existed.'),

  ('mission-ai-data-is-the-world-08', 1, 'arjun', 'Scaling means adjusting numeric columns so they live on comparable ranges. Without it, a column measured in the thousands can drown out a column measured in single digits, purely because of its units, not because it actually matters more.'),
  ('mission-ai-data-is-the-world-08', 2, 'byte', 'Distance-based methods feel this hardest. If one feature ranges zero to fifty thousand and another ranges zero to one, the first effectively decides every distance calculation on its own.'),
  ('mission-ai-data-is-the-world-08', 3, 'arjun', 'Two scaling techniques come up constantly: normalization and standardization. They are not the same thing, and picking the wrong one for the job causes quiet, hard-to-spot errors.'),

  ('mission-ai-data-is-the-world-09', 1, 'arjun', 'Normalization, specifically min-max normalization, rescales a column into a fixed range, usually zero to one, using nothing but that column''s own minimum and maximum.'),
  ('mission-ai-data-is-the-world-09', 2, 'arjun', 'That makes it bounded and easy to interpret, but it has a real weakness: a single extreme outlier stretches the whole range, and squeezes every other value toward one end.'),

  ('mission-ai-data-is-the-world-10', 1, 'arjun', 'Standardization, or z-score scaling, recenters a column around a mean of zero with a standard deviation of one, using value minus mean, divided by standard deviation.'),
  ('mission-ai-data-is-the-world-10', 2, 'arjun', 'Unlike normalization, the result is not bounded to a fixed range, but it holds up far better when the data has a roughly typical spread -- and it is what most statistical methods already assume the input looks like.'),

  ('mission-ai-data-is-the-world-11', 1, 'arjun', 'Everything the last several missions covered -- missing values, duplicates, outliers, encoding, scaling -- all feeds one bigger question: is this data actually good enough to trust a conclusion built on it?'),
  ('mission-ai-data-is-the-world-11', 2, 'arjun', 'Data quality is not one check, it is several: completeness, how much is missing. Uniqueness, how much is duplicated. Validity, whether values fall inside sane, possible ranges. Consistency, whether related fields agree with each other.'),
  ('mission-ai-data-is-the-world-11', 3, 'arjun', 'The recovered fragments have not been through a real quality pass yet. Before this Act closes, that changes.'),

  ('mission-ai-data-is-the-world-12', 1, 'arjun', 'This is the sample. Real fragments, pulled from the same decommissioned storage records-recovery found. If it holds up, it is the closest anyone has come to seeing what Echo actually trained on.'),
  ('mission-ai-data-is-the-world-12', 2, 'maya', 'Which is exactly why we do not skip a single check. Three passes -- missing values, duplicates, corrupted values -- the same three problems that break every recovered dataset, and probably this one too.'),
  ('mission-ai-data-is-the-world-12', 3, 'arjun', 'Agreed. I am not going to pretend I am not excited. I am also not going to let excited skip a step.'),
  ('mission-ai-data-is-the-world-12', 4, 'maya', 'Good. Because wanting this to be real is not the same as it being clean enough to build anything on. Run the audit. Let the evidence say what it says.'),
  ('mission-ai-data-is-the-world-12', 5, 'arjun', 'Whatever we conclude after this only holds if the cleanup underneath it actually holds.'),
  ('mission-ai-data-is-the-world-12', 6, 'maya', 'Clean or not, this is the closest anyone has come to Echo''s original data. What we do with it next decides whether the record can be trusted at all.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-data-is-the-world-01-o1', 'mission-ai-data-is-the-world-01', 1, 'Assess the recovery', 'Find the evidence that actually supports treating the recovered fragments as a credible lead.'),
  ('mission-ai-data-is-the-world-01-o2', 'mission-ai-data-is-the-world-01', 2, 'Separate the source from the hope', 'Identify the risk that gets introduced at the data collection stage itself.'),

  ('mission-ai-data-is-the-world-02-o1', 'mission-ai-data-is-the-world-02', 1, 'Sort the columns', 'Sort each recovered column into numerical, categorical, or text.'),
  ('mission-ai-data-is-the-world-02-o2', 'mission-ai-data-is-the-world-02', 2, 'Explain why it matters', 'State why a column''s data type has to be known before analysis begins.'),

  ('mission-ai-data-is-the-world-03-o1', 'mission-ai-data-is-the-world-03', 1, 'Find the disguised gap', 'Identify which field sample actually contains disguised missing values.'),
  ('mission-ai-data-is-the-world-03-o2', 'mission-ai-data-is-the-world-03', 2, 'Explain the sentinel', 'Explain why a repeated impossible value is most likely a stand-in for missing data.'),

  ('mission-ai-data-is-the-world-04-o1', 'mission-ai-data-is-the-world-04', 1, 'Find the exact duplicate', 'Identify the row pair that is an exact duplicate.'),
  ('mission-ai-data-is-the-world-04-o2', 'mission-ai-data-is-the-world-04', 2, 'Handle the near-duplicate', 'Choose the safest first step for a pair of rows that are similar but not identical.'),

  ('mission-ai-data-is-the-world-05-o1', 'mission-ai-data-is-the-world-05', 1, 'Spot the corrupted value', 'Identify the value that is most likely a corrupted outlier rather than a genuine rare event.'),
  ('mission-ai-data-is-the-world-05-o2', 'mission-ai-data-is-the-world-05', 2, 'Handle the genuine outlier', 'Choose the appropriate treatment for an extreme value with a known, real cause.'),

  ('mission-ai-data-is-the-world-06-o1', 'mission-ai-data-is-the-world-06', 1, 'Nominal or ordinal', 'Sort each categorical column into nominal or ordinal.'),
  ('mission-ai-data-is-the-world-06-o2', 'mission-ai-data-is-the-world-06', 2, 'Explain the block', 'State why raw category labels cannot simply be fed into most models as text.'),

  ('mission-ai-data-is-the-world-07-o1', 'mission-ai-data-is-the-world-07', 1, 'Choose the encoding', 'Pick the encoding technique that fits a column with a genuine order.'),
  ('mission-ai-data-is-the-world-07-o2', 'mission-ai-data-is-the-world-07', 2, 'Match technique to column', 'Match each categorical column to the encoding technique that actually fits it.'),

  ('mission-ai-data-is-the-world-08-o1', 'mission-ai-data-is-the-world-08', 1, 'Predict the effect', 'State what happens to an unscaled distance calculation when one column has a much larger range.'),
  ('mission-ai-data-is-the-world-08-o2', 'mission-ai-data-is-the-world-08', 2, 'Confirm the dominance', 'Find the evidence that proves scaling is actually needed before comparing these records.'),

  ('mission-ai-data-is-the-world-09-o1', 'mission-ai-data-is-the-world-09', 1, 'Define normalization', 'Identify what min-max normalization actually rescales a column by.'),
  ('mission-ai-data-is-the-world-09-o2', 'mission-ai-data-is-the-world-09', 2, 'Debug the function', 'Find the line of code that produces incorrect normalized values.'),

  ('mission-ai-data-is-the-world-10-o1', 'mission-ai-data-is-the-world-10', 1, 'Define standardization', 'Identify what standardization actually recenters a column by.'),
  ('mission-ai-data-is-the-world-10-o2', 'mission-ai-data-is-the-world-10', 2, 'Pick the right tool', 'Sort each scenario into normalization or standardization.'),

  ('mission-ai-data-is-the-world-11-o1', 'mission-ai-data-is-the-world-11', 1, 'Find the biggest risk', 'Identify which quality check affects the largest share of the sample.'),
  ('mission-ai-data-is-the-world-11-o2', 'mission-ai-data-is-the-world-11', 2, 'Name the other failure', 'State what can still be wrong with data that is complete and duplicate-free.'),

  ('mission-ai-data-is-the-world-12-o1', 'mission-ai-data-is-the-world-12', 1, 'Audit for missing values', 'Find the field sample that shows a real missing-values problem in the recovered fragments.'),
  ('mission-ai-data-is-the-world-12-o2', 'mission-ai-data-is-the-world-12', 2, 'Audit for duplicates', 'Find the evidence that shows an actual duplicate row in the recovered fragments.'),
  ('mission-ai-data-is-the-world-12-o3', 'mission-ai-data-is-the-world-12', 3, 'Audit for corrupted values', 'Find the field sample that shows a corrupted or impossible value in the recovered fragments.'),
  ('mission-ai-data-is-the-world-12-o4', 'mission-ai-data-is-the-world-12', 4, 'State the verdict', 'Having audited all three problems, state Cipher Division''s verdict on the recovered fragments.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-data-is-the-world-01-o1-c1', 'mission-ai-data-is-the-world-01-o1', 1, 'investigation', 'Which evidence actually supports treating these fragments as a credible lead on Echo''s training data?', '{"evidence":[{"id":"e1","label":"Storage imaging log","detail":"Drives were imaged bit-for-bit before analysis, preserving whatever survived the original decommission wipe"},{"id":"e2","label":"Format check","detail":"Recovered fragments contain structured records matching Cipher Labs known training-pipeline schema -- field names, record boundaries, timestamps"},{"id":"e3","label":"Facilities memo","detail":"The storage room housing the drives was scheduled for demolition next quarter, unrelated to this sweep"}],"question":"Which evidence actually supports treating these fragments as a credible lead on Echo''s training data?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-data-is-the-world-01-o2-c1', 'mission-ai-data-is-the-world-01-o2', 1, 'multiple_choice', 'Which of these is a risk introduced at the data collection stage itself, and that no later cleaning step can fix?', '{"question":"Which of these is a risk introduced at the data collection stage itself, and that no later cleaning step can fix?","options":[{"id":"a","text":"The dataset contains a typo in a column name"},{"id":"b","text":"The collection method systematically leaves out certain kinds of examples, so they are simply never captured in the first place"},{"id":"c","text":"Two rows happen to be exact duplicates"},{"id":"d","text":"A numeric column was stored as text"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-data-is-the-world-02-o1-c1', 'mission-ai-data-is-the-world-02-o1', 1, 'drag_and_drop', 'Sort each recovered column into numerical, categorical, or text.', '{"items":[{"id":"i1","text":"age_years: 34, 51, 22, 40"},{"id":"i2","text":"region_code: NA-1, NA-2, EU-4"},{"id":"i3","text":"session_notes: free-form operator comments"},{"id":"i4","text":"latency_ms: 112, 98, 340"},{"id":"i5","text":"status_flag: active, retired, unknown"}],"targets":[{"id":"numerical","label":"Numerical"},{"id":"categorical","label":"Categorical"},{"id":"text","label":"Text"}]}'::jsonb, '{"correctMapping":{"i1":"numerical","i2":"categorical","i3":"text","i4":"numerical","i5":"categorical"}}'::jsonb),
  ('mission-ai-data-is-the-world-02-o2-c1', 'mission-ai-data-is-the-world-02-o2', 1, 'multiple_choice', 'Why does a column''s data type matter before analysis begins?', '{"question":"Why does a column''s data type matter before analysis begins?","options":[{"id":"a","text":"It does not, all data becomes numbers eventually"},{"id":"b","text":"It determines which operations and techniques are even valid to apply to that column"},{"id":"c","text":"It only affects how the column is displayed on screen"},{"id":"d","text":"Only numeric columns need a type at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-data-is-the-world-03-o1-c1', 'mission-ai-data-is-the-world-03-o1', 1, 'investigation', 'Which field sample actually contains disguised missing values?', '{"evidence":[{"id":"e1","label":"Field sample: response_latency_ms","detail":"Column contains values like 88, 140, 205, and 47 rows of exactly -999"},{"id":"e2","label":"Field sample: session_id","detail":"Column contains unique alphanumeric identifiers for every row, no repeats"},{"id":"e3","label":"Field sample: record_date","detail":"Dates range smoothly across an eighteen-month window with no gaps"}],"question":"Which field sample actually contains disguised missing values?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-03-o2-c1', 'mission-ai-data-is-the-world-03-o2', 1, 'multiple_choice', 'A numeric latency column cannot physically be negative, but 47 rows show exactly -999. What is the most likely explanation?', '{"question":"A numeric latency column cannot physically be negative, but 47 rows show exactly -999. What is the most likely explanation?","options":[{"id":"a","text":"The sensor recorded a real negative latency"},{"id":"b","text":"-999 is very likely a placeholder value standing in for missing data"},{"id":"c","text":"The column is actually categorical"},{"id":"d","text":"Nothing is wrong, negative numbers are fine here"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-data-is-the-world-04-o1-c1', 'mission-ai-data-is-the-world-04-o1', 1, 'investigation', 'Which pair is an exact duplicate that should be flagged?', '{"evidence":[{"id":"e1","label":"Row comparison, rows 118 and 402","detail":"Every field matches exactly: same session_id, same timestamp, same latency, same outcome"},{"id":"e2","label":"Row comparison, rows 55 and 56","detail":"Same session_id, but response_latency_ms differs by 2ms and timestamps differ by one second"},{"id":"e3","label":"Row comparison, rows 900 and 901","detail":"Completely different session_ids, dates a week apart"}],"question":"Which pair is an exact duplicate that should be flagged?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-04-o2-c1', 'mission-ai-data-is-the-world-04-o2', 1, 'multiple_choice', 'Rows 55 and 56 share the same session_id but differ by 2ms and one second in their timestamps. What is the safest first step?', '{"question":"Rows 55 and 56 share the same session_id but differ by 2ms and one second in their timestamps. What is the safest first step?","options":[{"id":"a","text":"Delete both immediately"},{"id":"b","text":"Treat them as an exact duplicate and merge without checking"},{"id":"c","text":"Investigate whether this is the same event logged twice by overlapping recovery blocks, rather than assuming either way"},{"id":"d","text":"Ignore it, small differences never matter"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-ai-data-is-the-world-05-o1-c1', 'mission-ai-data-is-the-world-05-o1', 1, 'investigation', 'Which value is most likely a corrupted outlier rather than a genuine rare event?', '{"evidence":[{"id":"e1","label":"Field sample: session_duration_sec","detail":"Column ranges 2 to 340 seconds for 4,000 rows, except one row that reads 2,147,483 seconds"},{"id":"e2","label":"Field sample: request_count","detail":"Column ranges 1 to 40 for most rows, one row reads 312 during a known traffic-spike incident logged separately"},{"id":"e3","label":"Field sample: user_region","detail":"Categorical column with expected regional codes throughout"}],"question":"Which value is most likely a corrupted outlier rather than a genuine rare event?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-05-o2-c1', 'mission-ai-data-is-the-world-05-o2', 1, 'multiple_choice', 'The request_count of 312 lines up with a documented traffic-spike incident. What is the appropriate treatment?', '{"question":"The request_count of 312 lines up with a documented traffic-spike incident. What is the appropriate treatment?","options":[{"id":"a","text":"Delete it, it is far from the average"},{"id":"b","text":"Keep it -- it is an extreme but genuine value with a known cause, not an error"},{"id":"c","text":"Replace it with the column average"},{"id":"d","text":"Convert it to a missing value"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-data-is-the-world-06-o1-c1', 'mission-ai-data-is-the-world-06-o1', 1, 'drag_and_drop', 'Sort each categorical column into nominal or ordinal.', '{"items":[{"id":"i1","text":"region_code: north, south, east, west"},{"id":"i2","text":"priority_level: low, medium, high"},{"id":"i3","text":"device_type: sensor, terminal, relay"},{"id":"i4","text":"risk_tier: tier-1, tier-2, tier-3, tier-4"},{"id":"i5","text":"status_flag: active, retired, unknown"}],"targets":[{"id":"nominal","label":"Nominal (no real order)"},{"id":"ordinal","label":"Ordinal (real order)"}]}'::jsonb, '{"correctMapping":{"i1":"nominal","i2":"ordinal","i3":"nominal","i4":"ordinal","i5":"nominal"}}'::jsonb),
  ('mission-ai-data-is-the-world-06-o2-c1', 'mission-ai-data-is-the-world-06-o2', 1, 'multiple_choice', 'Why can categorical values like north and south not simply be fed into most models as raw text?', '{"question":"Why can categorical values like north and south not simply be fed into most models as raw text?","options":[{"id":"a","text":"Models can read text labels directly with no issue"},{"id":"b","text":"Most models require numeric input, and raw text categories have no inherent numeric value"},{"id":"c","text":"Categorical columns are always errors"},{"id":"d","text":"Only ordinal categories need conversion"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-data-is-the-world-07-o1-c1', 'mission-ai-data-is-the-world-07-o1', 1, 'multiple_choice', 'priority_level has the values low, medium, high, in that real order. Which encoding fits best?', '{"question":"priority_level has the values low, medium, high, in that real order. Which encoding fits best?","options":[{"id":"a","text":"One-hot encoding"},{"id":"b","text":"Ordinal encoding, since a genuine order exists"},{"id":"c","text":"No encoding needed, leave it as text"},{"id":"d","text":"Random numeric assignment"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-data-is-the-world-07-o2-c1', 'mission-ai-data-is-the-world-07-o2', 1, 'drag_and_drop', 'Match each categorical column to the encoding technique that fits it.', '{"items":[{"id":"i1","text":"priority_level: low, medium, high"},{"id":"i2","text":"region_code: north, south, east, west"},{"id":"i3","text":"risk_tier: tier-1, tier-2, tier-3, tier-4"},{"id":"i4","text":"device_type: sensor, terminal, relay"}],"targets":[{"id":"ordinal","label":"Ordinal / label encoding"},{"id":"onehot","label":"One-hot encoding"}]}'::jsonb, '{"correctMapping":{"i1":"ordinal","i2":"onehot","i3":"ordinal","i4":"onehot"}}'::jsonb),

  ('mission-ai-data-is-the-world-08-o1-c1', 'mission-ai-data-is-the-world-08-o1', 1, 'multiple_choice', 'A dataset has session_duration_sec ranging 0-50000 and error_rate ranging 0-1. Left unscaled, what happens in a distance-based comparison?', '{"question":"A dataset has session_duration_sec ranging 0-50000 and error_rate ranging 0-1. Left unscaled, what happens in a distance-based comparison?","options":[{"id":"a","text":"Both columns contribute equally regardless of scale"},{"id":"b","text":"session_duration_sec dominates the distance calculation purely because of its larger numeric range"},{"id":"c","text":"error_rate always dominates"},{"id":"d","text":"Scale never affects distance-based methods"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-data-is-the-world-08-o2-c1', 'mission-ai-data-is-the-world-08-o2', 1, 'investigation', 'Which evidence shows scaling is actually needed before comparing these records?', '{"evidence":[{"id":"e1","label":"Comparison test","detail":"When two records are compared, session_duration_sec alone accounts for over 99% of the computed distance, unrelated to actual similarity"},{"id":"e2","label":"Column description","detail":"error_rate is bounded strictly between 0 and 1 by definition"},{"id":"e3","label":"Metadata","detail":"Both columns were recorded by the same logging system at the same interval"}],"question":"Which evidence shows scaling is actually needed before comparing these records?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-data-is-the-world-09-o1-c1', 'mission-ai-data-is-the-world-09-o1', 1, 'multiple_choice', 'Min-max normalization rescales values using...', '{"question":"Min-max normalization rescales values using...","options":[{"id":"a","text":"The column''s mean and standard deviation"},{"id":"b","text":"The column''s minimum and maximum values"},{"id":"c","text":"A fixed constant unrelated to the data"},{"id":"d","text":"The median only"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-data-is-the-world-09-o2-c1', 'mission-ai-data-is-the-world-09-o2', 1, 'code_debugging', 'This function is supposed to min-max normalize a column into the 0-1 range. Which line contains the bug?', '{"language":"python","code":"def normalize(column):\n    minimum = column.min()\n    maximum = column.max()\n    return (column - minimum) / maximum","question":"This function is supposed to min-max normalize a column into the 0-1 range. Which line contains the bug?"}'::jsonb, '{"requiredLineIds":["    return (column - minimum) / maximum"]}'::jsonb),

  ('mission-ai-data-is-the-world-10-o1-c1', 'mission-ai-data-is-the-world-10-o1', 1, 'multiple_choice', 'Standardization recenters a column using...', '{"question":"Standardization recenters a column using...","options":[{"id":"a","text":"The column''s minimum and maximum"},{"id":"b","text":"The column''s mean and standard deviation"},{"id":"c","text":"A fixed range of zero to one always"},{"id":"d","text":"The column''s median and range"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-data-is-the-world-10-o2-c1', 'mission-ai-data-is-the-world-10-o2', 1, 'drag_and_drop', 'Sort each scenario into normalization or standardization.', '{"items":[{"id":"i1","text":"A neural network input layer that expects every feature strictly bounded between 0 and 1"},{"id":"i2","text":"A statistical method that assumes roughly Gaussian-distributed input"},{"id":"i3","text":"Image pixel values that need a fixed 0-1 range for display"},{"id":"i4","text":"A dataset with a roughly typical spread, headed into a distance-based clustering method sensitive to relative spread"}],"targets":[{"id":"normalization","label":"Normalization"},{"id":"standardization","label":"Standardization"}]}'::jsonb, '{"correctMapping":{"i1":"normalization","i2":"standardization","i3":"normalization","i4":"standardization"}}'::jsonb),

  ('mission-ai-data-is-the-world-11-o1-c1', 'mission-ai-data-is-the-world-11-o1', 1, 'investigation', 'Taken together, which check reveals the largest share of affected rows in this sample?', '{"evidence":[{"id":"e1","label":"Completeness check","detail":"Roughly 6% of numeric fields are empty or disguised as sentinel values across the sample"},{"id":"e2","label":"Uniqueness check","detail":"Around 3% of rows appear to be exact or near-duplicates from overlapping recovery blocks"},{"id":"e3","label":"Validity check","detail":"A small number of numeric fields contain values physically outside any possible real range"}],"question":"Taken together, which check reveals the largest share of affected rows in this sample?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-11-o2-c1', 'mission-ai-data-is-the-world-11-o2', 1, 'multiple_choice', 'A dataset can be 100% complete, have zero duplicates, and still be low quality. What could still be wrong?', '{"question":"A dataset can be 100% complete, have zero duplicates, and still be low quality. What could still be wrong?","options":[{"id":"a","text":"Nothing else could be wrong"},{"id":"b","text":"Values could be present but invalid or inconsistent -- for example a timestamp that predates the system''s creation, or two fields that contradict each other"},{"id":"c","text":"Data quality is only ever about missing values"},{"id":"d","text":"Only duplicates matter"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-data-is-the-world-12-o1-c1', 'mission-ai-data-is-the-world-12-o1', 1, 'investigation', 'Which field sample shows a real missing-values problem in the recovered fragments?', '{"evidence":[{"id":"e1","label":"Field sample: input_token_count","detail":"412 of 6,000 sampled rows show exactly 0 where every surrounding row has a plausible token count between 4 and 900"},{"id":"e2","label":"Field sample: fragment_id","detail":"Every row carries a unique, non-empty fragment identifier"},{"id":"e3","label":"Field sample: recovery_block","detail":"Block numbers increase steadily with no unexplained jumps"}],"question":"Which field sample shows a real missing-values problem in the recovered fragments?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-12-o2-c1', 'mission-ai-data-is-the-world-12-o2', 1, 'investigation', 'Which evidence shows an actual duplicate row in the recovered fragments?', '{"evidence":[{"id":"e1","label":"Row comparison, rows 2201 and 4877","detail":"Identical across every field: same fragment_id, same input_token_count, same recovery_block, same timestamp"},{"id":"e2","label":"Row comparison, rows 300 and 6001","detail":"Different fragment_ids, similar but not identical token counts"},{"id":"e3","label":"Block overlap report","detail":"Two recovery blocks were imaged from adjacent, non-overlapping disk sectors"}],"question":"Which evidence shows an actual duplicate row in the recovered fragments?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-12-o3-c1', 'mission-ai-data-is-the-world-12-o3', 1, 'investigation', 'Which field sample shows a corrupted or impossible value in the recovered fragments?', '{"evidence":[{"id":"e1","label":"Field sample: fragment_timestamp","detail":"One row carries a timestamp several decades before Cipher Labs existed, inconsistent with every surrounding row"},{"id":"e2","label":"Field sample: input_token_count","detail":"Values cluster between 4 and 900, consistent with the rest of the sample"},{"id":"e3","label":"Field sample: fragment_id","detail":"Formatted consistently with the known Cipher Labs training-pipeline schema"}],"question":"Which field sample shows a corrupted or impossible value in the recovered fragments?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-data-is-the-world-12-o4-c1', 'mission-ai-data-is-the-world-12-o4', 1, 'boss_encounter', 'Having audited all three problems, state Cipher Division''s verdict on the recovered fragments.', '{"stages":[{"objectiveRef":"mission-ai-data-is-the-world-12-o1","label":"Audit for missing values"},{"objectiveRef":"mission-ai-data-is-the-world-12-o2","label":"Audit for duplicates"},{"objectiveRef":"mission-ai-data-is-the-world-12-o3","label":"Audit for corrupted values"}],"task":"State the verdict in one sentence: the recovered fragments are real, but too damaged by missing values, duplicates and corrupted values to draw firm conclusions from until real cleanup happens."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-data-is-the-world-12-o1","mission-ai-data-is-the-world-12-o2","mission-ai-data-is-the-world-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-data-is-the-world-01-o1-c1', 'orientation', 'The strongest evidence for a real lead is structural, not procedural -- ask which item shows the fragments actually resemble training data.', 10, 1),
  ('mission-ai-data-is-the-world-01-o1-c1', 'solution', 'e2: the recovered fragments match Cipher Labs known training-pipeline schema -- field names, record boundaries, timestamps -- which is direct structural evidence, not just a chain-of-custody detail.', 20, 2),
  ('mission-ai-data-is-the-world-01-o2-c1', 'orientation', 'A typo or a duplicate row can be fixed after the fact. This risk cannot be fixed after the fact.', 10, 1),
  ('mission-ai-data-is-the-world-01-o2-c1', 'solution', 'If the collection method never captured certain kinds of examples in the first place, no amount of later cleaning can add them back in.', 20, 2),

  ('mission-ai-data-is-the-world-02-o1-c1', 'orientation', 'Ask whether the values are numbers you could average, labels from a limited set, or free-form writing.', 10, 1),
  ('mission-ai-data-is-the-world-02-o1-c1', 'solution', 'Numerical: age_years, latency_ms. Categorical: region_code, status_flag. Text: session_notes.', 20, 2),
  ('mission-ai-data-is-the-world-02-o2-c1', 'orientation', 'Think about what happens if you try to average a column that is actually a category code.', 10, 1),
  ('mission-ai-data-is-the-world-02-o2-c1', 'solution', 'A column''s type decides which operations are even valid on it -- averaging a categorical code produces a number with no real meaning.', 20, 2),

  ('mission-ai-data-is-the-world-03-o1-c1', 'orientation', 'Look for a value that is repeated far too often and is physically impossible for the field.', 10, 1),
  ('mission-ai-data-is-the-world-03-o1-c1', 'concept', 'A latency in milliseconds can never be negative -- a suspiciously exact, repeated negative value is a placeholder, not a measurement.', 20, 2),
  ('mission-ai-data-is-the-world-03-o1-c1', 'solution', 'e1: 47 rows of exactly -999 in a latency column is a classic disguised-missing-value pattern.', 30, 3),
  ('mission-ai-data-is-the-world-03-o2-c1', 'orientation', 'A real sensor reading would not repeat the exact same impossible number 47 separate times.', 10, 1),
  ('mission-ai-data-is-the-world-03-o2-c1', 'solution', '-999 is a common placeholder convention standing in for a missing measurement, not a genuine negative latency.', 20, 2),

  ('mission-ai-data-is-the-world-04-o1-c1', 'orientation', 'An exact duplicate matches on every single field, not just one or two.', 10, 1),
  ('mission-ai-data-is-the-world-04-o1-c1', 'solution', 'e1: rows 118 and 402 match on session_id, timestamp, latency, and outcome -- a true exact duplicate.', 20, 2),
  ('mission-ai-data-is-the-world-04-o2-c1', 'orientation', 'A small timestamp gap alongside a matching session_id looks like recovery overlap, not automatically a duplicate or automatically distinct.', 10, 1),
  ('mission-ai-data-is-the-world-04-o2-c1', 'solution', 'The safest move is to investigate the cause -- overlapping recovery blocks logging the same event twice -- before deciding to merge, delete, or keep both rows.', 20, 2),

  ('mission-ai-data-is-the-world-05-o1-c1', 'orientation', 'Compare each extreme value against what is physically possible for that field, not just against the average.', 10, 1),
  ('mission-ai-data-is-the-world-05-o1-c1', 'concept', 'A session lasting over two million seconds is roughly 24,000 days -- that is not a rare real event, it is a corrupted value.', 20, 2),
  ('mission-ai-data-is-the-world-05-o1-c1', 'solution', 'e1: session_duration_sec of 2,147,483 seconds is physically implausible and most likely a corrupted or overflowed value.', 30, 3),
  ('mission-ai-data-is-the-world-05-o2-c1', 'orientation', 'This outlier has a documented, independent cause -- that changes how it should be treated.', 10, 1),
  ('mission-ai-data-is-the-world-05-o2-c1', 'solution', 'Because the spike lines up with a known traffic incident, it is a genuine extreme value and should be kept, not deleted or averaged away.', 20, 2),

  ('mission-ai-data-is-the-world-06-o1-c1', 'orientation', 'Ask whether the categories have a natural ranking, or whether they could be listed in any order with no loss of meaning.', 10, 1),
  ('mission-ai-data-is-the-world-06-o1-c1', 'solution', 'Ordinal: priority_level, risk_tier (both have a real ranking). Nominal: region_code, device_type, status_flag (no inherent order).', 20, 2),
  ('mission-ai-data-is-the-world-06-o2-c1', 'orientation', 'Most models operate on numbers under the hood, not on the meaning of words.', 10, 1),
  ('mission-ai-data-is-the-world-06-o2-c1', 'solution', 'Raw text categories have no numeric value a model can compute with, so nearly all models require categories to be converted to numbers first.', 20, 2),

  ('mission-ai-data-is-the-world-07-o1-c1', 'orientation', 'Ordinal encoding is only appropriate when the categories actually have a real ranking.', 10, 1),
  ('mission-ai-data-is-the-world-07-o1-c1', 'solution', 'low, medium, high has a genuine order, so ordinal encoding fits -- mapping them to 0, 1, 2 preserves a meaning that is really there.', 20, 2),
  ('mission-ai-data-is-the-world-07-o2-c1', 'orientation', 'Columns with a real order take ordinal encoding. Columns without one take one-hot encoding.', 10, 1),
  ('mission-ai-data-is-the-world-07-o2-c1', 'solution', 'Ordinal: priority_level, risk_tier. One-hot: region_code, device_type.', 20, 2),

  ('mission-ai-data-is-the-world-08-o1-c1', 'orientation', 'Distance calculations are sensitive to the raw magnitude of each column''s numbers, not their real-world importance.', 10, 1),
  ('mission-ai-data-is-the-world-08-o1-c1', 'solution', 'session_duration_sec dominates purely because its range is fifty thousand times larger than error_rate''s -- nothing about actual relevance.', 20, 2),
  ('mission-ai-data-is-the-world-08-o2-c1', 'orientation', 'Look for evidence that directly measures one column overwhelming a calculation, not just a description of its range.', 10, 1),
  ('mission-ai-data-is-the-world-08-o2-c1', 'solution', 'e1: session_duration_sec alone accounts for over 99% of the computed distance -- direct proof that scaling is needed before comparison.', 20, 2),

  ('mission-ai-data-is-the-world-09-o1-c1', 'orientation', 'Think about what two numbers define the fixed range a normalized column gets squeezed into.', 10, 1),
  ('mission-ai-data-is-the-world-09-o1-c1', 'solution', 'Min-max normalization uses the column''s own minimum and maximum to rescale it, usually into the zero-to-one range.', 20, 2),
  ('mission-ai-data-is-the-world-09-o2-c1', 'orientation', 'Trace the formula by hand for a value equal to the minimum -- the result should be 0, but check whether the code actually produces that.', 10, 1),
  ('mission-ai-data-is-the-world-09-o2-c1', 'concept', 'Min-max normalization is (value - minimum) / (maximum - minimum), not (value - minimum) / maximum.', 20, 2),
  ('mission-ai-data-is-the-world-09-o2-c1', 'solution', 'The return line divides by maximum alone instead of (maximum - minimum), so the output is only correctly bounded to 0-1 when minimum is exactly 0.', 30, 3),

  ('mission-ai-data-is-the-world-10-o1-c1', 'orientation', 'Standardization does not produce a fixed range -- it produces a fixed shape, centered on a specific value.', 10, 1),
  ('mission-ai-data-is-the-world-10-o1-c1', 'solution', 'Standardization recenters a column using its own mean and standard deviation, producing a mean of 0 and a standard deviation of 1.', 20, 2),
  ('mission-ai-data-is-the-world-10-o2-c1', 'orientation', 'A fixed, bounded display range points to normalization. An assumption about typical spread or distribution shape points to standardization.', 10, 1),
  ('mission-ai-data-is-the-world-10-o2-c1', 'solution', 'Normalization: the neural network input needing 0-1, image pixel values needing a fixed display range. Standardization: the Gaussian-assuming statistical method, the spread-sensitive clustering method.', 20, 2),

  ('mission-ai-data-is-the-world-11-o1-c1', 'orientation', 'Compare the percentages directly -- one check affects a clearly larger share of the sample than the others.', 10, 1),
  ('mission-ai-data-is-the-world-11-o1-c1', 'solution', 'e1: roughly 6% of numeric fields affected by completeness issues is the largest measured share among the three checks.', 20, 2),
  ('mission-ai-data-is-the-world-11-o2-c1', 'orientation', 'Completeness and uniqueness are only two of several quality dimensions -- think about whether the values that are present actually make sense.', 10, 1),
  ('mission-ai-data-is-the-world-11-o2-c1', 'solution', 'Data can be fully present and unique while still being invalid or inconsistent -- an impossible timestamp or two fields that contradict each other are quality failures with nothing to do with missing values or duplicates.', 20, 2),

  ('mission-ai-data-is-the-world-12-o1-c1', 'orientation', 'Look for a value that repeats suspiciously often where a real, varying measurement is expected.', 10, 1),
  ('mission-ai-data-is-the-world-12-o1-c1', 'solution', 'e1: 412 rows showing exactly 0 for input_token_count, surrounded by rows with plausible non-zero counts, is a real missing-values pattern.', 20, 2),
  ('mission-ai-data-is-the-world-12-o2-c1', 'orientation', 'An exact duplicate matches on every field, not just a similar value.', 10, 1),
  ('mission-ai-data-is-the-world-12-o2-c1', 'solution', 'e1: rows 2201 and 4877 match on fragment_id, input_token_count, recovery_block and timestamp -- a genuine duplicate.', 20, 2),
  ('mission-ai-data-is-the-world-12-o3-c1', 'orientation', 'A timestamp that predates the organization that created the data is physically impossible, not just unusual.', 10, 1),
  ('mission-ai-data-is-the-world-12-o3-c1', 'solution', 'e1: a fragment_timestamp several decades before Cipher Labs existed cannot be a genuine value -- it is corrupted.', 20, 2),
  ('mission-ai-data-is-the-world-12-o4-c1', 'orientation', 'Weigh what all three audits found together, not just whether the fragments look promising overall.', 15, 1),
  ('mission-ai-data-is-the-world-12-o4-c1', 'solution', 'The recovered fragments are real -- the schema and structure hold up -- but missing spans, duplicated blocks and corrupted values mean any conclusion drawn from them now would only be as trustworthy as the cleanup done first.', 25, 2);
